import React from "react";
import { useState } from "react";
import logo from "./logo.svg";
import "./App.css";

function App() {
  const [isCallendarMenuVisible, setIsCallendarMenuVisible] = useState(false);

  const toggleCallendarsMenu = () => {
    setIsCallendarMenuVisible(!isCallendarMenuVisible);
  };

  const [isMenuVisible, setIsMenuVisible] = useState(false);

  const toggleMenu = () => {
    setIsMenuVisible(!isMenuVisible);
  };

  return (
    <>
      <div
        className={`slide-menu slide-menu-grid  ${
          isMenuVisible ? "visible" : ""
        }`}
      >
        <div className=""></div>
        <button className="close-icon slide-main-menu-close"></button>
        <p className="slide-menu-header-title-item">Menu</p>
      </div>

      <div
        className={`slide-callendar-menu slide-menu-grid ${
          isCallendarMenuVisible ? "visible" : ""
        }`}
      >
        <div className="slide-menu-header-item-1">
          <button
            className="slide-menu-header-close close-icon"
            onClick={toggleCallendarsMenu}
          ></button>
          <p className="slide-menu-header-title-item">Callendars</p>
        </div>
      </div>
      <div className="body-container body-grid">
        <div className="navbar navbar-grid">
          <p className="workflow-logo navbar-logo-item-1 ">WorkFlow</p>
          <div className="navbar-menubar navbar-button-group">
            <button className="navbar-todo-button"> To Do</button>
            <button className="navbar-notes-button">Notes</button>
            <button className="navbar-chat-button">Chat</button>
            <button className="navbar-schedule-button">Schedule</button>
          </div>
          <button
            className="navbar-menu-list menu-list-icon"
            onClick={toggleMenu}
          ></button>
        </div>
        <div className="left-sidebar sidebar-grid">
          <button className="sidebar-item-10 left-arrow-icon"></button>
          <button
            className="sidebar-item-1 callendar-icon"
            onClick={toggleCallendarsMenu}
          ></button>
        </div>
        <div className="right-sidebar sidebar-grid">
          <button className="sidebar-item-10 right-arrow-icon"></button>
        </div>
        <div className="center-container">
          <div className="center-container-grid">
            <div className="carousel-layout center-container-item-1">
              <div className="carousel-row-1">
                <div className="todo-list-body carousel-row-item-1"></div>
                <div className="todo-list-body carousel-row-item-2"></div>
                <div className="todo-list-body carousel-row-item-3"></div>
                <div className="todo-list-body carousel-row-item-4"></div>
                <div className="todo-list-body carousel-row-item-5"></div>
                <div className="todo-list-body carousel-row-item-6"></div>
              </div>

              <div className="carousel-row-2">
                <div className="todo-list-body carousel-row-item-1"></div>
                <div className="todo-list-body carousel-row-item-2"></div>
                <div className="todo-list-body carousel-row-item-3"></div>
                <div className="todo-list-body carousel-row-item-4"></div>
                <div className="todo-list-body carousel-row-item-5"></div>
                <div className="todo-list-body carousel-row-item-6"></div>
              </div>
            </div>

            <div className="other-tasks center-container-item-2"></div>
          </div>
        </div>
      </div>
    </>
  );
}

export default App;
